pragma solidity 0.8.36;
library L {
    function cd(bytes calldata self) internal pure returns (uint) { return self.length; }
    function mem(bytes memory self) internal pure returns (uint) { return self.length; }
    function store(bytes storage self) internal view returns (uint) { return self.length; }
}
contract C {
    using L for bytes;
    bytes value;
    function calldataReceiver(bytes calldata input) external pure returns (uint) { return input.cd() + input.mem(); }
    function memoryReceiver(bytes memory input) public pure returns (uint) { return input.mem(); }
    function storageReceiver() external view returns (uint) { return value.store() + value.mem(); }
}
